package dev.mixer.android;
import java.util.*;
/** Passive actual value/reference recorder. It cannot decide product authority. */
public final class OutcomeCapture {
 final List<Object> rows=new ArrayList<>();private boolean ended,latchedClean;private Throwable latchedFailure;
 /** Passive evidence faults dirty this attempt and never replace a product return/exception. */
 static boolean observe(Runnable action){try{action.run();return true;}catch(RuntimeException|Error failure){NativeOutcomeProbe.captureFailed(failure);return false;}}
 void begin(){begin(null);}
 void begin(DirectBoundaryStates.Trace trace){NativeOutcomeProbe.begin(value->{Map<String,Object> row=new LinkedHashMap<>();row.put("method",value.method());row.put("descriptor",value.descriptor());row.put("completion",value.completion());row.put("receiver_identity",DirectBoundaryStates.identity(value.receiver()));row.put("value",actual(value.value()));row.put("original_exception_class",value.originalException()==null?null:value.originalException().getClass().getName());row.put("original_exception_identity",DirectBoundaryStates.identity(value.originalException()));List<Object> frames=new ArrayList<>();for(var f:FullFrames.complete(value.productionFrames()))frames.add(Map.of("class",f.className(),"method",f.methodName(),"descriptor",f.descriptor(),"bci",f.bytecodeIndex(),"line",f.line()));row.put("production_frames",frames);if(trace!=null)row.putAll(trace.outcomeEvent(value,frames));rows.add(row);});}
 void end(){NativeOutcomeProbe.end();latchedClean=NativeOutcomeProbe.clean();latchedFailure=NativeOutcomeProbe.captureFailure();ended=true;}
 boolean clean(){return ended&&latchedClean;}
 Map<String,Object> diagnostic(){Map<String,Object> out=new LinkedHashMap<>();out.put("ended",ended);out.put("clean_latched",latchedClean);out.put("capture_failure_class",latchedFailure==null?null:latchedFailure.getClass().getName());out.put("capture_failure_message",latchedFailure!=null&&latchedFailure.getClass()==AssertionError.class?latchedFailure.getMessage():null);return out;}
 private static Map<String,Object> field(String name,String type,Object value){Map<String,Object> out=new LinkedHashMap<>();out.put("field",name);out.put("type",type);out.put("value",value);return Collections.unmodifiableMap(out);}
 private static String text(Object value){if(value==null)return null;if(value instanceof String s)return s;if(value instanceof android.text.Editable){Object backing=DirectBoundaryStates.get(value,"text");if(backing instanceof StringBuilder b)return b.toString();}throw new AssertionError("unselected mutable text implementation");}
 static Object actual(Object value){
  if(value==null)return Map.of("kind","null");if(value instanceof Boolean)return Map.of("kind","boolean","value",value);if(value instanceof Integer||value instanceof Long||value instanceof Short||value instanceof Byte)return Map.of("kind","integer","value",value);if(value instanceof Float||value instanceof Double)return Map.of("kind","floating","value",value);if(value instanceof Character)return Map.of("kind","character","value",String.valueOf(value));if(value instanceof String)return Map.of("kind","string","value",value,"identity",DirectBoundaryStates.identity(value));
  List<Object> fields=new ArrayList<>();
  if(value instanceof android.view.inputmethod.ExtractedText x){fields.add(field("text","java.lang.CharSequence:string",text(x.text)));fields.add(field("startOffset","int",x.startOffset));fields.add(field("partialStartOffset","int",x.partialStartOffset));fields.add(field("partialEndOffset","int",x.partialEndOffset));fields.add(field("selectionStart","int",x.selectionStart));fields.add(field("selectionEnd","int",x.selectionEnd));fields.add(field("flags","int",x.flags));}
  else if(value instanceof android.view.inputmethod.SurroundingText){fields.add(field("text","java.lang.CharSequence:string",text(DirectBoundaryStates.get(value,"text"))));fields.add(field("start","int",DirectBoundaryStates.get(value,"start")));fields.add(field("end","int",DirectBoundaryStates.get(value,"end")));fields.add(field("offset","int",DirectBoundaryStates.get(value,"offset")));}
  else if(value instanceof android.view.inputmethod.TextSnapshot){fields.add(field("text","android.view.inputmethod.SurroundingText",actual(DirectBoundaryStates.get(value,"text"))));}
  else if(value instanceof android.text.Editable){String captured=text(value);if(captured.length()>1048576)throw new AssertionError("bounded mutable text capture");fields.add(field("text","java.lang.String",captured));Object spans=DirectBoundaryStates.get(value,"spans");if(!(spans instanceof List<?> selected)||selected.size()>4096)throw new AssertionError("bounded selected span list");List<Object> snapshot=new ArrayList<>();for(Object span:selected){snapshot.add(List.of(field("object","identity",DirectBoundaryStates.identity(DirectBoundaryStates.get(span,"object"))),field("start","int",DirectBoundaryStates.get(span,"start")),field("end","int",DirectBoundaryStates.get(span,"end")),field("flags","int",DirectBoundaryStates.get(span,"flags"))));}fields.add(field("spans","ordered-span-records",List.copyOf(snapshot)));}
  Map<String,Object> out=new LinkedHashMap<>();out.put("kind",fields.isEmpty()?"reference":"typed-snapshot");out.put("class",value.getClass().getName());out.put("identity",DirectBoundaryStates.identity(value));if(!fields.isEmpty())out.put("fields",List.copyOf(fields));return Collections.unmodifiableMap(out);
 }
}
